INSERT INTO soups (id,title,story,answer,hints,author_name,status,created_at,published_at,language,creator_token) VALUES
  ('seed-classic-albatross','海鸟汤','男人尝了一口餐厅的海鸟汤，反复向厨师确认用的是什么肉。得到答复后，他付钱离开，当晚结束了自己的生命。汤没有毒，厨师也没有骗他。','男人曾与妻子遭遇海难。流落荒岛后，妻子死去，同伴给饥饿的他吃了一份肉，称是海鸟肉。获救后，他尝到真正的海鸟汤，发觉与岛上的味道完全不同，追问同伴，得知自己当时吃下的是妻子的遗体。他无法承受真相，最终自杀。','["他曾和妻子一起流落荒岛，妻子在那里死去。","岛上的同伴曾给他吃肉，并告诉他那是海鸟肉。","获救后，他联系当年的同伴，得知那顿肉来自妻子的遗体。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-short-match','半根火柴','沙漠中发现一名坠落身亡的男人。他没有穿衣服，手里攥着半根未烧过的火柴。附近散落着衣物和行李，却没有飞机残骸。','他与同伴乘坐的热气球失去高度。众人抛下行李，连衣物也丢掉，仍在下坠。他们约定抽火柴，抽到短签的人离开吊篮，为其他人减轻重量。男人抽中了被折短的那根，履行约定后坠亡。','["他原本和几名同伴一起乘坐正在失去高度的热气球。","他们先后丢弃重物和衣服，希望减轻吊篮的负担。","众人用长短不同的火柴抽签，决定谁必须离开吊篮。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-lighthouse','熄灯之后','男人睡前关掉一盏灯。第二天，他看见远处的残骸，知道许多陌生人因自己而死。他整夜没有离开住处。','他是灯塔看守人，关掉了夜间为船只导航的灯。那晚一艘船失去这处航标的指引，撞上附近的礁石，造成多人死亡。早晨看到海上的残骸，他才意识到自己熄灯的后果。','["他的工作是为夜间航行的船只提供指引。","住处附近的海域有危险的礁石。","那艘船在灯熄灭后失去了航标，撞上了礁石。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-music-stopped','音乐停止以后','音乐突然停了。女人随即迈出一步，坠落身亡。没有人碰她，也没有人要求她去死。','她正在蒙眼表演高空走钢丝，下面没有保护网。她与乐队约定，到达终点平台时才停止演奏。当晚乐队误提前停了音乐，她以为脚边已经是平台，迈出钢丝后踏空坠亡。','["她正在蒙眼完成一场高空表演。","她与乐队约定，用停止演奏表示已到达终点平台。","她脚下是钢丝，下面没有保护网；乐队当晚提前停奏了。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-iced-drinks','喝得慢的人','两人喝下同一壶茶倒出的冰饮。一人很快喝完几杯，另一人只慢慢喝了一杯。后来，慢喝的人中毒身亡，快喝的人活了下来。','毒物藏在冰块里。快喝的人在冰块大量融化前喝完，留下了冰块，摄入量很少；慢喝的人让冰块逐渐融化，喝入了足以致命的毒物。决定结果的是饮用时间和冰块的变化。','["茶壶里的茶没有毒，毒物在后来加入杯中的东西里。","快喝的人喝完就留下了尚未融化的大部分冰块。","慢喝者杯里的冰逐渐融化，把里面的毒物释放进茶水。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-rewound-tape','倒回开头的遗言','男人死在桌边，旁边留着枪和磁带录音机。警察只按了一次播放键，便听见他的告别与一声枪响。听完，警察开始调查是谁布置了这个现场。','录音机只能手动倒带。凶手逼男人录下告别，随后杀死他；为了让来人听到“遗言”，又把磁带倒回开头。录音包含死亡时的枪声，而警察直接播放就能从告别开始听，说明有人在枪响后操作过机器。','["这台录音机没有自动倒带功能。","枪响发生在录音过程中，男人随后已经无法再操作机器。","有人强迫他录下告别，杀害他后又动过磁带。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-one-way-ticket','没有回程的旅客','一则游客失足落海的消息，让售票员放下了早餐。他不认识死者，却马上联系警方，说有人在出发前就知道她不会回来。','售票员记得死者的丈夫为两人安排行程时，给自己买了往返票，却只给妻子买了单程票。丈夫当时还明确说两人会一同回家。读到妻子落海的消息后，售票员察觉这两件事的矛盾，将购票记录交给警方，成为调查丈夫预谋杀人的线索。','["两人的票都是丈夫买的，而且出发前就已买好。","丈夫买票时声称夫妻俩会一起回来。","购票记录中，只有丈夫拥有回程票，妻子拿的是单程票。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-subway-pact','地铁上的旧约','地铁上，一个独臂男人认出了多年不见的旧友。旧友抬起双手向他打招呼，他却当场开枪杀死了对方。两人曾一起获救。','他们曾与其他人一起遭遇海难。绝境中，众人约定轮流牺牲一条手臂作为食物。轮到最后一人之前，救援到来；他逃走了，拒绝履行这个残酷约定。独臂男人多年后认出他，看见他双臂完好，因怨恨而将他杀害。','["两人在一次海难后曾被困在没有食物的地方。","当年的人约定轮流牺牲一条手臂，用来让其他人活下去。","救援赶在旧友履约前到来；他获救后逃走，拒绝付出同样的代价。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-birthday-surprise','门后的生日快乐','男人在家门外杀死妻子，随后推门进去。灯突然亮了，一群人向他喊生日快乐。他原本准备离开这座城市，此刻却瘫坐在地上。','男人打算杀妻后独自逃走，以为屋里没人。妻子提前安排了惊喜派对，请亲友躲在黑暗的屋内，等夫妻回家再开灯祝寿。男人把妻子的遗体拖过门口时，等候的人正好打开灯，亲眼看到现场。他的逃亡计划因此暴露。','["妻子是这场聚会的组织者，丈夫事先毫不知情。","亲友按她的安排，提前躲进了屋里。","开灯时，丈夫正把妻子的遗体拖进门，亲友看到了这一幕。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-dark-motel','唯一没亮的房间','深夜，男人在旅馆停车场不停按喇叭。窗户一扇接一扇亮起，只有一间始终漆黑。他道了歉，走向那间房，终于找到了妻子。','男人到车里取东西，回来时忘了房号。小旅馆当晚客满，各间门窗又很相似。他的妻子听不见声音，仍在房内睡觉。他按喇叭后，其他房客这次都被吵醒并亮灯查看，妻子所在的房间没有动静，他据此找回了房间。','["他先前去车里取东西，回来时忘记了房号。","他的妻子听不见声音，当时正在房内睡觉。","这家旅馆当晚客满；其他房客被吵醒后都开灯查看。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-unopened-pack','来不及打开的包','空旷的田野里躺着一个死人，背上的包还没有打开。周围没有车辆，也没有任何走向他的脚印。找到他的人说，那个包本来能救他。','他从飞机上跳伞，降落伞发生故障，未能展开，最终坠落在田野里。背包就是伞包。现场没有走来的脚印，因为他从空中到达那里。','["他离开飞机后，在下降途中出了事故。","那个包的用途是在空中减慢下落速度。","包里的降落伞发生故障，没能展开。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-sunken-cards','赢家先死','我从窗外看见两个死人，桌上散着纸牌，旁边有一把枪。一个人中枪，另一个人溺水。他们最后一局的赢家，是中枪的那个。','我是一名潜水员，看到的是沉船里的舱室。船下沉时，两人被困，枪里只剩一发子弹。他们害怕溺水，于是打牌决定谁能用这发子弹先结束生命。赢家中枪死去，另一人随后随舱室进水而溺亡。','["窗外的目击者是一名潜水员，正查看沉船。","两人被困在无法逃出的舱室里，枪中只剩一发子弹。","牌局决定谁能先使用那发子弹，避免随后溺水的痛苦。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-bar-hiccups','酒保的枪','男人走进酒吧要了一杯水。酒保忽然举枪对准他。他愣了一下，说了声谢谢，连水也没喝就走了。','男人一直打嗝，想喝水缓解。酒保从他说话的声音听出了问题，故意用枪吓他。惊吓使这次打嗝停了，他便道谢离开。','["男人要水，是为了缓解一种身体不适。","酒保从男人说话时断续的声音发现了问题。","举枪带来的惊吓，恰好让那种不适停止了。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-rainy-elevator','下雨才到家','男人住十楼。晴天独自回家，他坐电梯到七楼，再走三层楼梯；下雨时却能直接坐到十楼。下楼时，他每天都能直接到一楼。','男人个子很矮，伸手只能按到七楼的按钮。一楼按钮位置低，下楼没有困难。下雨时他随身带伞，可以用伞尖按到十楼。','["电梯的楼层按钮从低到高排列，十楼按钮在较高处。","男人的身高使他伸手只能碰到部分按钮。","下雨时，他手里多了一把能延长触及距离的伞。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-broken-fishbowl','安东尼与克莉奥佩特拉','安东尼与克莉奥佩特拉死在房间地板上，旁边有水和碎玻璃。身上没有伤口，也没有中毒。现场唯一的目击者是一条狗。','安东尼与克莉奥佩特拉是两条金鱼。狗碰倒了鱼缸，玻璃碎裂，水流到地上。两条鱼离水后死亡。','["狗在事发时碰倒了一个装水的玻璃容器。","死者平时一直生活在那个容器里。","它们的呼吸依赖水中的氧气。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-silent-phone-call','一句话也没说','男人躺在床上，怎么也睡不着。他拨通一个电话，等对方接起后，一句话也没说就挂断了。随后他终于能安心入睡。','他住在旅馆，隔壁房客的鼾声让他无法入睡。他打通隔壁房间的电话，铃声把对方叫醒，鼾声暂时停止，他便趁这段安静睡着了。','["他住在旅馆，睡眠被隔壁传来的声音打断。","接电话的人就是那个声音的来源。","电话铃把正在打鼾的邻居叫醒了。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-night-watchman','救命之后被解雇','守夜人劝老板取消航班，说自己昨夜梦见那架飞机失事。老板照办，飞机果然坠毁。老板重金酬谢他，随后却把他解雇了。','老板感谢他让自己躲过空难，但守夜人所说的昨夜正是他的值班时间。他承认做梦，也就暴露了值班时睡觉的失职行为。','["昨夜是守夜人的工作时间。","他的工作要求整夜保持清醒。","老板把预警的帮助与值班时睡着这件事分别处理。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-sawdust-cane','地上的木屑','男人死了。房里的一点木屑，本来足以让他活下来，可他始终没有发现。木屑究竟说明了什么？','男人失明，靠极矮的身材在马戏团谋生。竞争者偷偷锯短他的手杖。他发现熟悉的手杖变矮，误以为自己长高、即将失去生计，绝望自杀。木屑是手杖被锯过的痕迹，能揭穿这个骗局。','["他失明，依靠触觉判断身边物品的位置。","他的收入来自马戏团对其矮小身材的展示。","竞争者动过他的木手杖，手杖的长度变了。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-tunnel-light','隧道里的一点火光','火车进入隧道后，男人突然绝望，想结束自己的生命。远处的一点火光，却让他立刻放弃了这个念头。那点光没有照亮出口。','男人刚做完恢复视力的手术，正在返程。没有内部照明的车厢进入隧道，他误以为自己再次失明。看到别人的香烟火光后，他发现自己仍能看见，只是周围太暗。','["他刚做过眼部手术，这趟车是回程。","当时车厢没有内部照明。","那点光来自乘客的香烟，让他确认自己的眼睛仍能看见。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-melted-support','空房间里的水','门从里面锁住，房间没有窗户。男人悬挂在高处，已经死亡。脚下没有桌椅或梯子，只有一摊水。他之前借助的东西去了哪里？','房间里原本有一块供他垫脚的冰。人死后，冰逐渐融化成水，因此现场没有留下桌椅之类的支撑物。','["他曾借助一个可以承重的固体垫高自己。","房间温度使那件物品逐渐改变了形态。","地上的水就是那个支撑物留下的全部残余。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-fifty-three-cards','第五十三张牌','男人死在牌桌旁。桌上和地上共有五十三张扑克牌，没有大小王。调查者数完牌，便明白了这场争执的起因。','这场牌局本应使用去掉大小王后的五十二张牌。死者藏了一张额外的牌作弊，被其他玩家发现后遭到杀害。第五十三张牌暴露了出千。','["这场牌局约定只用一副去掉大小王的牌。","死者曾把一张额外的牌藏在身上。","其他赌客发现他出千后，与他发生了冲突。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-mountain-cabin','山上的小舱室','山坡上一间小舱室里，两个穿制服的男人都死了。附近有火烧过的痕迹，但他们在起火前就已死亡。那里发生了什么？','那是撞上山坡的飞机驾驶舱。两人是飞行员，死于撞击；随后才发生火灾。小舱室是飞机残骸的一部分。','["两人的制服表明，他们在这里从事相同的工作。","这间舱室原本属于一件交通工具。","两人遭遇的致命撞击发生在火灾之前。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-second-funeral','再办一次葬礼','在母亲的葬礼上，女人对一个陌生男人一见钟情。她没能留下对方的联系方式。几天后，她杀死了自己的妹妹。为什么？','她希望妹妹的葬礼能再次把那名男人吸引来。她把第一次相遇的场合当成重新见到他的办法，因此制造了另一场家人的葬礼。','["她采取行动的目标，是再见到那个男人。","妹妹的死亡会让家里再次举行一种聚会。","她认为参加过母亲葬礼的人，也可能参加妹妹的葬礼。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-counting-floors','对面的手指','我从亮着灯的房间里看见对面有人行凶。凶手发现了我，却没有马上逃走。他抬起手，手指沿着我这栋楼一层层移动。我更害怕了。','凶手在数楼层和窗口，确认目击者住在哪里。他想找上门灭口，因此先记住我的位置。我害怕的是他正在确定我的住址。','["凶手已经把我当成需要处理的目击者。","他的手指在逐层对应这栋楼的窗户。","他打算到我所在的房间来。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-window-portraits','木屋里的肖像','猎人在森林迷路，借宿一间空木屋。墙上一张张逼真的脸令他整夜不安。天亮后，那些脸都不见了。他看清四周，才知道昨晚有多危险。','他在黑暗中误认了窗框。那些脸是从屋外透过窗户盯着他的人。天亮后，窗外的人离开了，透进来的日光让他看清屋里根本没有那些肖像。','["那些脸出现的位置，白天会透进日光。","猎人昨晚看见的框，属于房屋本身。","脸的主人当时站在屋外，正朝里面看。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-fatal-ringtone','最后一通电话','丈夫给妻子打了一通电话。妻子还没接听，就因此被人杀死。丈夫不想伤害她，也不知道危险正在发生。','家中闯入了歹徒，妻子躲起来，手机却没有静音。丈夫的来电让铃声响起，暴露了藏身处，歹徒因此找到她并杀害了她。','["妻子当时正在家里躲避一名入侵者。","她随身带着手机，并且没有关闭铃声。","入侵者靠声音确定了她的藏身位置。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-five-in-rain','雨中的五个人','五个人一起去教堂，途中突然下雨。四个人开始跑，浑身湿透。第五个人没有自己走一步，却和他们同时抵达，身上也没有淋湿。','四个人抬着棺材去教堂参加葬礼，第五个人是棺中的死者。他由其他人抬着移动，棺材挡住了雨水。','["四个人正共同搬运一件有盖的大物件。","第五个人在那件物品里面，由他们抬着前进。","他们去教堂是为了参加一场葬礼。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-bodies-in-well','井里最后一个人','男人每次杀人，都把尸体丢进一口井。第二天，尸体总会消失。多年后，他把母亲也丢了进去。可这一次，无论等多久，尸体都还在。','母亲一直暗中替儿子掩盖罪行，把井里的尸体移走。她死后，再也没有人替他做这件事，所以她的尸体一直留在井中。','["此前有人在男人离开后，悄悄处理井里的尸体。","那个人知道他的罪行，却长期选择包庇他。","母亲生前就是替他善后的那个人。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-missing-bride','没有离开的新娘','婚礼上，新娘和宾客玩起捉迷藏。大家一直找不到她，以为她逃婚了。多年后，老宅里的一个箱子被打开，人们才发现她从来没有离开。','新娘当年躲进阁楼的一只旧箱子，箱盖意外锁住，无法从里面打开。没人找到她，她死在里面。多年后开启箱子，才发现遗体，解开失踪之谜。','["游戏开始后，她独自去了老宅的阁楼。","她挑选的藏身处是一只有盖的旧箱子。","箱盖合上后锁住了，里面没有能打开它的装置。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed'),
  ('seed-classic-two-pills','总能活下来的那个人','绑匪拿出两颗外观相同的药，说一颗有毒，让人质先选。他吃剩下的一颗。两人各喝面前杯里的水送服，结果每次都是人质死去，绑匪活下来。','两颗药都是无毒的糖片，绑匪关于毒药的说法是谎言。人质面前那杯水被下了毒，绑匪的水是安全的。选择哪颗药都不会改变结果。','["绑匪对药片的介绍中，有一句是他编造的。","那两颗药都是无毒的糖片。","毒物只在提供给人质的水里。"]','Jev 题库','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','zh','seed')
